#!/usr/bin/env node
/**
 * Refresh the frozen baseline artifacts.
 *
 *   node tests/fixtures/update-pre-migration.mjs
 *
 * Two things are frozen here, for different reasons:
 *
 *   pre-migration-values.json  — every brand value as it existed in the wild
 *     before press generated any of it. This is the migration's no-op proof and
 *     should almost never be regenerated: rewriting it to match a change is how
 *     you would erase the evidence that the change broke a shipped product.
 *     Regenerate ONLY when adding a newly-discovered pre-existing source.
 *
 *   golden/<target>.txt        — the exact bytes each target's region should
 *     contain. The region *is* the contract, so byte-exactness is right here
 *     (the same call shipflow makes for its rendered workflow). Regenerate
 *     whenever an emitter or a token deliberately changes, and read the diff.
 */
import { writeFileSync, mkdirSync, readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { loadTokens } from '../../lib/tokens.mjs';
import { emitBody } from '../../lib/emit.mjs';
import { loadTargets } from '../../lib/targets.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const GOLDEN = join(HERE, 'golden');

const tokens = loadTokens();
const targets = loadTargets();

// Goldens pin the SHAPE of each emitter's output, not the release it ran from.
// The version-badge embeds its version, so using the real one would churn every
// golden on every release and turn a drift detector into noise.
const GOLDEN_VERSION = '0.0.0';

mkdirSync(GOLDEN, { recursive: true });
for (const target of targets) {
  const body = emitBody(tokens, target.emitter, target.params ?? {}, { version: GOLDEN_VERSION });
  writeFileSync(join(GOLDEN, `${target.id}.txt`), `${body}\n`, 'utf8');
}

/**
 * The floor is carried forward, never re-derived.
 *
 * It was previously a literal in this file, which meant every refresh silently
 * rewrote whatever the manifest recorded back down to that literal — so raising
 * the floor after adding targets was impossible, and the anti-vacuity guarantee
 * quietly weakened with every new consumer. Raising it is now a deliberate edit
 * to the manifest; lowering it is refused here, because a shrinking registry is
 * exactly what the floor exists to notice.
 */
const previous = existsSync(join(GOLDEN, 'manifest.json'))
  ? JSON.parse(readFileSync(join(GOLDEN, 'manifest.json'), 'utf8')).min_targets ?? 0
  : 0;
if (targets.length < previous) {
  throw new Error(
    `${targets.length} targets resolved but the floor is ${previous} — targets.json lost a consumer, ` +
      'or the resolver is matching nothing. Fix that, or lower min_targets by hand and say why.',
  );
}

const manifest = {
  $comment:
    'Byte-exact expected region body per target. Regenerated by update-pre-migration.mjs; read the diff before committing. min_targets is carried forward, never re-derived — raise it by hand when adding a consumer.',
  min_targets: previous,
  targets: targets.map((t) => t.id),
};
writeFileSync(join(GOLDEN, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`, 'utf8');

process.stdout.write(`wrote ${targets.length} goldens to tests/fixtures/golden/\n`);
process.stdout.write(
  `pre-migration-values.json left untouched (${
    Object.keys(JSON.parse(readFileSync(join(HERE, 'pre-migration-values.json'), 'utf8')).sources).length
  } sources) — edit it by hand only, and say why.\n`,
);
